parameters.jsCode:
const aiText = $input.first().json.candidates[0].content.parts[0].text;
const cleaned = aiText.replace(/```json|```/g, '').trim();
const ai = JSON.parse(cleaned);
const webhookData = $('Webhook (nuevo lead)').first().json.body;

return {
  lead_id: webhookData.lead_id || webhookData.id,
  lead_score: ai.score,
  lead_category: ai.category,
  lead_insight: ai.insight,
  lead_recommendation: ai.recomendacion,
  lead_nombre: webhookData.nombre,
  lead_email: webhookData.email,
  lead_compania: webhookData.compania,
  status: ai.score >= 7 ? 'demo' : ai.score >= 4 ? 'contacted' : 'new',
  value: Math.round(ai.score * 100),
  notas: `[IA] Score: ${ai.score}/10 | ${ai.insight}`
};

const parsed = $('Parsear respuesta IA').first().json;
const nombre = parsed.lead_nombre || 'cliente';
const compania = parsed.lead_compania || 'su empresa';
const score = parsed.lead_score || 5;
const insight = parsed.lead_insight || 'optimizar sus procesos operativos';
const recomendacion = parsed.lead_recommendation || 'agendar una auditoria gratuita';

let subject = `Propuesta inicial para ${compania} - Agencia ANGULO`;

let body = `Hola ${nombre},\n\n`;
body += `Gracias por contactar a ANGULO. Tras analizar la informacion de ${compania}, nuestro sistema de IA ha identificado que: ${insight}.\n\n`;

if (score >= 7) {
  body += `Esto es una gran oportunidad. ${recomendacion}.\n\n`;
  body += `Podemos agendar una auditoria gratuita esta misma semana para mostrarle exactamente como ANGULO puede transformar su operacion.\n\n`;
} else if (score >= 4) {
  body += `Creemos que hay potencial para mejorar. ${recomendacion}.\n\n`;
  body += `Le proponemos una llamada de 15 minutos sin compromiso para entender mejor sus necesidades.\n\n`;
} else {
  body += `Aunque en este momento no detectamos urgencia inmediata, ${recomendacion}. Le mantendremos informado sobre como ANGULO puede ayudar a empresas como ${compania}.\n\n`;
}

body += `Que tenga un excelente dia,\nEquipo ANGULO\nwww.angulosoftware.com\nWhatsApp: +58 424 9313359`;

return { subject, body, toEmail: parsed.lead_email };
